# K1: is the admiral oracle usable?
#   K1a: do the admiral templates regenerate pharmaverseadam?
#   K1b: metamorphic test: shift every SDTM --DTC forward 4 years, rerun the templates,
#        expect baseline output with every date shifted +4 years.
# Run from the repo root:  Rscript r/k1_oracle_check.R
# Templates are generated by admiral::use_ad_template() into results/k1/templates/ (git-ignored).
# Each template runs in a fresh Rscript process (r/run_template.R) with its data reads
# redirected through shims and cut at its "Save output" block (the originals write to a
# user-level cache directory).

suppressPackageStartupMessages({
  library(dplyr)
  library(lubridate)
  library(jsonlite)
})

out_dir <- "results/k1"
tmpl_dir <- file.path(out_dir, "templates")
log_dir <- file.path(out_dir, "logs")
dir.create(log_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(tmpl_dir, recursive = TRUE, showWarnings = FALSE)

templates <- c(adsl = "ad_adsl.R", adae = "ad_adae.R", adlb = "ad_adlb.R")
sdtm_domains <- c("dm", "ds", "ex", "ae", "lb")
key_candidates <- list(
  adsl = list("USUBJID"),
  adae = list(c("USUBJID", "ASEQ"), c("USUBJID", "AESEQ")),
  adlb = list(c("USUBJID", "ASEQ"), c("USUBJID", "LBSEQ"), c("USUBJID", "PARAMCD", "VISITNUM", "LBSEQ"))
)
YEARS <- 4
TOL <- 1e-8

# Step 1: generate the templates (installed signature: no `open` argument)
for (n in names(templates)) {
  admiral::use_ad_template(adam_name = n, save_path = file.path(tmpl_dir, templates[[n]]),
                           package = "admiral", overwrite = TRUE)
}

# ---- shims ------------------------------------------------------------------------------

run_template <- function(name, sdtm_override = NULL, adsl_override = NULL) {
  tmp <- function(x) {
    if (is.null(x)) return("NA")
    f <- tempfile(fileext = ".rds"); saveRDS(x, f); f
  }
  out <- tempfile(fileext = ".rds")
  status <- system2("Rscript", c("r/run_template.R", name, file.path(tmpl_dir, templates[[name]]),
                                 tmp(sdtm_override), tmp(adsl_override), out),
                    stdout = FALSE, stderr = file.path(log_dir, paste0("worker_", name, ".err")))
  if (status != 0 || !file.exists(out)) stop("template ", name, " failed; see ", log_dir, "/worker_", name, ".err")
  readRDS(out)
}

shift_year_chr <- function(x, n) {
  ok <- !is.na(x) & grepl("^[0-9]{4}", x)
  x[ok] <- paste0(as.integer(substr(x[ok], 1, 4)) + n, substring(x[ok], 5))
  x
}

shift_sdtm <- function(df, n = YEARS) {
  for (v in names(df)) {
    if (is.character(df[[v]]) && grepl("DTC$", v)) {
      lab <- attr(df[[v]], "label")
      df[[v]] <- shift_year_chr(df[[v]], n)
      attr(df[[v]], "label") <- lab
    }
  }
  df
}

# Expected output of the perturbed run: baseline output with every date/datetime/--DTC shifted
shift_output <- function(df, n = YEARS) {
  for (v in names(df)) {
    x <- df[[v]]
    lab <- attr(x, "label")
    if (inherits(x, "Date") || inherits(x, "POSIXct")) {
      df[[v]] <- x %m+% years(n)
    } else if (is.character(x) && grepl("DTC$", v)) {
      df[[v]] <- shift_year_chr(x, n)
    }
    attr(df[[v]], "label") <- lab
  }
  df
}

# ---- comparison -------------------------------------------------------------------------

make_key <- function(df, keys) do.call(paste, c(lapply(df[keys], as.character), sep = "\r"))

pick_keys <- function(ref, new, name) {
  for (k in key_candidates[[name]]) {
    if (all(k %in% names(ref)) && all(k %in% names(new)) &&
        !anyDuplicated(make_key(ref, k)) && !anyDuplicated(make_key(new, k))) {
      return(list(keys = k, unique = TRUE))
    }
  }
  # fall back: first candidate present in both, made unique with an occurrence counter
  for (k in key_candidates[[name]]) {
    if (all(k %in% names(ref)) && all(k %in% names(new))) return(list(keys = k, unique = FALSE))
  }
  stop("no usable key for ", name)
}

col_equal <- function(a, b) {
  if (is.factor(a)) a <- as.character(a)
  if (is.factor(b)) b <- as.character(b)
  if ((is.numeric(a) || inherits(a, "Date") || inherits(a, "POSIXct")) &&
      (is.numeric(b) || inherits(b, "Date") || inherits(b, "POSIXct")) &&
      identical(class(a)[1], class(b)[1])) {
    a <- as.numeric(a); b <- as.numeric(b)
    (is.na(a) & is.na(b)) | (!is.na(a) & !is.na(b) & abs(a - b) <= TOL * pmax(1, abs(a)))
  } else {
    a <- as.character(a); b <- as.character(b)
    (is.na(a) & is.na(b)) | (!is.na(a) & !is.na(b) & a == b)
  }
}

compare_ds <- function(ref, new, name, label, log_file = NULL) {
  kk <- pick_keys(ref, new, name)
  keys <- kk$keys
  kref <- make_key(ref, keys); knew <- make_key(new, keys)
  if (!kk$unique) {
    kref <- paste(kref, ave(seq_along(kref), kref, FUN = seq_along))
    knew <- paste(knew, ave(seq_along(knew), knew, FUN = seq_along))
  }
  common_rows <- intersect(kref, knew)
  ri <- match(common_rows, kref); ni <- match(common_rows, knew)
  common_cols <- setdiff(intersect(names(ref), names(new)), character())
  mism <- vapply(common_cols, function(v) sum(!col_equal(ref[[v]][ri], new[[v]][ni])), numeric(1))
  type_diff <- common_cols[vapply(common_cols, function(v) {
    !identical(class(ref[[v]]), class(new[[v]]))
  }, logical(1))]
  label_diff <- common_cols[vapply(common_cols, function(v) {
    !identical(attr(ref[[v]], "label"), attr(new[[v]], "label"))
  }, logical(1))]
  if (!is.null(log_file)) {
    out <- tryCatch(
      capture.output(print(diffdf::diffdf(ref, new, keys = keys, suppress_warnings = TRUE))),
      error = function(e) paste("diffdf failed:", conditionMessage(e))
    )
    writeLines(c(paste("diffdf:", label), out), log_file)
  }
  list(
    label = label, dataset = name,
    keys = keys, keys_unique_in_ref = kk$unique,
    nrow_ref = nrow(ref), nrow_new = nrow(new),
    rows_only_in_ref = length(setdiff(kref, knew)),
    rows_only_in_new = length(setdiff(knew, kref)),
    rows_compared = length(common_rows),
    cols_ref = ncol(ref), cols_new = ncol(new),
    cols_only_in_ref = setdiff(names(ref), names(new)),
    cols_only_in_new = setdiff(names(new), names(ref)),
    vars_with_mismatch = as.list(mism[mism > 0]),
    n_vars_compared = length(common_cols),
    n_vars_mismatch = sum(mism > 0),
    type_diffs = type_diff,
    label_diffs = label_diff
  )
}

# ---- run --------------------------------------------------------------------------------

res <- list(k1a = list(), k1b = list(), runs = list())
note_run <- function(tag, r) {
  res$runs[[tag]] <<- list(seconds = round(r$seconds, 2), warnings = r$warnings,
                           nrow = nrow(r$data), ncol = ncol(r$data))
}

message("K1a: shipped templates vs pharmaverseadam")
a_adsl_pkg <- getExportedValue("pharmaverseadam", "adsl")
res$k1a$admiral_adsl_vs_pharmaverseadam_adsl <- compare_ds(
  a_adsl_pkg, getExportedValue("admiral", "admiral_adsl"), "adsl",
  "admiral::admiral_adsl vs pharmaverseadam::adsl", file.path(log_dir, "k1a_admiral_adsl.log"))
for (n in names(templates)) {
  r <- run_template(n)
  note_run(paste0("k1a_", n), r)
  res$k1a[[n]] <- compare_ds(getExportedValue("pharmaverseadam", n), r$data, n,
                             paste0("template ", n, " vs pharmaverseadam::", n),
                             file.path(log_dir, paste0("k1a_", n, ".log")))
}

message("K1b: baseline chain vs shifted-SDTM chain")
sdtm_base <- setNames(lapply(sdtm_domains, function(d) getExportedValue("pharmaversesdtm", d)), sdtm_domains)
sdtm_shift <- lapply(sdtm_base, shift_sdtm)
res$k1b$sdtm_cols_shifted <- unlist(lapply(names(sdtm_base), function(d) {
  v <- names(sdtm_base[[d]])
  v <- v[vapply(v, function(x) is.character(sdtm_base[[d]][[x]]) && grepl("DTC$", x), logical(1))]
  if (length(v)) paste0(d, ".", v)
}))

run_chain <- function(sdtm, tag) {
  adsl <- run_template("adsl", sdtm_override = sdtm); note_run(paste0(tag, "_adsl"), adsl)
  adae <- run_template("adae", sdtm_override = sdtm, adsl_override = adsl$data); note_run(paste0(tag, "_adae"), adae)
  adlb <- run_template("adlb", sdtm_override = sdtm, adsl_override = adsl$data); note_run(paste0(tag, "_adlb"), adlb)
  list(adsl = adsl$data, adae = adae$data, adlb = adlb$data)
}
base <- run_chain(NULL, "k1b_base")
pert <- run_chain(sdtm_shift, "k1b_pert")
for (n in names(templates)) {
  res$k1b[[n]] <- compare_ds(shift_output(base[[n]]), pert[[n]], n,
                             paste0(n, ": shifted baseline vs perturbed run"),
                             file.path(log_dir, paste0("k1b_", n, ".log")))
  # control: unshifted baseline vs perturbed shows the shift is visible in the data
  res$k1b[[paste0(n, "_control_unshifted")]] <- compare_ds(base[[n]], pert[[n]], n,
                                                           paste0(n, ": UNSHIFTED baseline vs perturbed (control)"))
  # informational: chained baseline vs the package dataset
  res$k1b[[paste0(n, "_chain_vs_pkg")]] <- compare_ds(getExportedValue("pharmaverseadam", n), base[[n]], n,
                                                      paste0(n, ": chained baseline vs pharmaverseadam"))
}

res$versions <- list(
  R = R.version.string,
  admiral = as.character(packageVersion("admiral")),
  pharmaversesdtm = as.character(packageVersion("pharmaversesdtm")),
  pharmaverseadam = as.character(packageVersion("pharmaverseadam")),
  diffdf = as.character(packageVersion("diffdf")),
  dplyr = as.character(packageVersion("dplyr")),
  lubridate = as.character(packageVersion("lubridate"))
)
write_json(res, file.path(out_dir, "k1_results.json"), auto_unbox = TRUE, pretty = TRUE, null = "null")
writeLines(capture.output(sessionInfo()), file.path(out_dir, "session_info.txt"))
message("wrote ", file.path(out_dir, "k1_results.json"))
